insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('financement-auto-credit','Financer sa voiture : crÃ©dit 6 Ã  84 mois et mensualitÃ©s dÃ¨s 139 â‚¬','2026-10-13','assets/img/bmw-x1.jpg','Acompte de 30 %, durÃ©es de 6 Ã  84 mois, acceptation en 24 h : le guide du financement auto simple et sans surprise.','["Le financement auto se rÃ©sume Ã  trois chiffres : l''acompte, la durÃ©e et la mensualitÃ©. Ce guide vous aide Ã  calibrer les trois sans mauvaise surprise, avec des exemples chiffrÃ©s.", "## L''apport : combien mettre ?", "Chez KlarDrive, la rÃ©servation demande 30 % d''acompte. Au-delÃ , tout apport supplÃ©mentaire rÃ©duit le montant financÃ© â€” et donc le coÃ»t total des intÃ©rÃªts. Exemple sur 20 000 â‚¬ : avec 6 000 â‚¬ d''apport, vous financez 14 000 â‚¬ ; avec 10 000 â‚¬, seulement 10 000 â‚¬.", "## La durÃ©e : 6 Ã  84 mois, comment choisir ?", "- **12â€“36 mois** : mensualitÃ©s Ã©levÃ©es, coÃ»t total minimum â€” idÃ©al si le budget suit", "- **48â€“60 mois** : l''Ã©quilibre le plus choisi (ex. 14 000 â‚¬ sur 60 mois â‰ˆ 260 â‚¬/mois selon taux)", "- **72â€“84 mois** : mensualitÃ©s dÃ¨s 139 â‚¬/mois, mais coÃ»t total supÃ©rieur â€” Ã  rÃ©server aux petits budgets mensuels", "RÃ¨gle d''or : la durÃ©e du crÃ©dit ne devrait jamais dÃ©passer la durÃ©e de dÃ©tention prÃ©vue du vÃ©hicule.", "## Le dossier qui passe en 24 h", "PrÃ©parez : piÃ¨ce d''identitÃ©, justificatifs de revenus des 3 derniers mois, relevÃ©s bancaires rÃ©cents, justificatif de domicile. Un dossier complet obtient gÃ©nÃ©ralement une acceptation de principe en 24 h. Les rejets viennent le plus souvent de dÃ©couverts rÃ©pÃ©tÃ©s ou d''un taux d''endettement au-delÃ  de 35 %.", "## Les piÃ¨ges Ã  Ã©viter", "- Ne comparez jamais que la mensualitÃ© : exigez le **TAEG et le coÃ»t total**", "- Refusez les assurances emprunteur imposÃ©es : la dÃ©lÃ©gation est un droit", "- MÃ©fiez-vous des Â« sans apport, sans justificatif Â» : les taux explosent", "## Simulez avec nous", "## LOA, LLD ou crÃ©dit classique ?", "Trois formules coexistent, pour trois profils :", "- **CrÃ©dit classique** : vous Ãªtes propriÃ©taire dÃ¨s le premier jour, libre de revendre quand vous voulez â€” notre recommandation dans 80 % des cas", "- **LOA (location avec option d''achat)** : mensualitÃ©s plus basses, valeur de rachat fixÃ©e Ã  l''avance â€” intÃ©ressant si vous changez de voiture tous les 3 ans", "- **LLD (location longue durÃ©e)** : entretien et assistance inclus, mais vous ne possÃ©dez jamais le vÃ©hicule", "MÃ©fiez-vous des LOA aux valeurs de rachat gonflÃ©es : le coÃ»t total dÃ©passe souvent le crÃ©dit classique. Demandez toujours les trois simulations chiffrÃ©es avant de signer.", "Envoyez-nous le vÃ©hicule visÃ© et votre apport sur [notre bon de commande](bon-de-commande.html) : notre Ã©quipe Ã  Bad Homburg vor der HÃ¶he monte votre dossier et vous rÃ©pond en moins d''une heure ouvrÃ©e, par e-mail Ã  contact@klardrive.de."]'::jsonb,'2026-01-01T01:40:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('garantie-occasion-jeune','Garantie auto d''occasion : 12 mois minimum et garantie constructeur','2026-10-12','assets/img/porsche-macan.jpg','Garantie lÃ©gale, extension 36 mois, Herstellergarantie restante : ce qui couvre vraiment votre occasion rÃ©cente en Allemagne.','["En Allemagne comme en France, tout professionnel doit garantir un vÃ©hicule d''occasion 12 mois minimum contre les vices non dÃ©clarÃ©s. C''est la base lÃ©gale : exigez-la par Ã©crit avant de signer.", "Sur les vÃ©hicules de moins de 4 ans, un bonus s''ajoute : la garantie constructeur restante (Herstellergarantie). Une BMW ou Mercedes de 2023 peut encore Ãªtre couverte par le constructeur : vÃ©rifiez la date de premiÃ¨re immatriculation et le carnet d''entretien.", "Chez KlarDrive, chaque vÃ©hicule affiche sa garantie : 12 mois minimum, extension possible jusqu''Ã  36 mois, et bÃ©nÃ©fice de la garantie constructeur restante quand elle existe. Notre rÃ©seau de garages partenaires intervient prÃ¨s de votre domicile.", "Vice cachÃ© ou panne aprÃ¨s l''achat ? Notre Ã©quipe Ã  Bad Homburg vor der HÃ¶he vous rÃ©pond par e-mail Ã  contact@klardrive.de et organise la prise en charge."]'::jsonb,'2026-01-01T01:41:00Z');
