insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('immatriculation-zulassung-allemagne','Zulassung : immatriculer une voiture importÃ©e en Allemagne','2026-10-06','assets/img/mercedes-glc.jpg','COC, HU, Zulassungsstelle, Kennzeichen : les 4 Ã©tapes pour immatriculer un vÃ©hicule importÃ©, gÃ©rÃ©es par KlarDrive.','["Immatriculer un vÃ©hicule importÃ© en Allemagne (Zulassung) fait peur Ã  beaucoup d''acheteurs â€” Ã  tort. Avec un dossier complet, c''est une formalitÃ© de quelques jours. Voici les 4 Ã©tapes, les piÃ¨ces exactes et les erreurs qui font perdre des semaines.", "## Les 4 piÃ¨ces obligatoires", "Sans l''un de ces documents, la Zulassungsstelle refuse l''immatriculation :", "- Le **certificat de conformitÃ© europÃ©en (COC)** : fourni par le constructeur, il prouve que le vÃ©hicule respecte les normes UE", "- Un **contrÃ´le technique (HU)** de moins de 6 mois, passÃ© en Allemagne", "- Une **piÃ¨ce d''identitÃ©** avec justificatif de domicile allemand (Meldebescheinigung)", "- Une **attestation d''assurance (eVB-Nummer)** dÃ©livrÃ©e par votre assureur en 5 minutes", "## Le passage en prÃ©fecture, Ã©tape par Ã©tape", "### 1. RÃ©server un crÃ©neau", "La plupart des Zulassungsstellen (dont celle de Bad Homburg) fonctionnent sur rendez-vous en ligne. Comptez 3 Ã  10 jours d''attente selon la pÃ©riode : anticipez.", "### 2. Le jour J", "PrÃ©sentez le dossier + les plaques d''immatriculation souhaitÃ©es (rÃ©servables en ligne, ~13 â‚¬ la paire frappÃ©e). L''agent vÃ©rifie, encaisse ~30 â‚¬ de taxes et Ã©dite la carte grise allemande (Zulassungsbescheinigung Teil I et II).", "### 3. Rouler lÃ©gal", "Vous repartez avec vos plaques posÃ©es et un vÃ©hicule 100 % en rÃ¨gle. Conservez le COC et les rapports HU avec les papiers : ils valoriseront la revente.", "## Les 3 erreurs qui bloquent tout", "- **COC manquant ou non conforme** : sans lui, il faut une rÃ©ception Ã  titre isolÃ© (Einzelabnahme) au TÃœV, 500 Ã  1 500 â‚¬ et des semaine