insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('hybride-ou-electrique','VÃ©hicule hybride ou Ã©lectrique : que choisir ?','2026-09-19','assets/img/toyota-chr.jpg','Autonomie, coÃ»t, entretien, Ã©cologie : le comparatif pour choisir entre hybride et Ã©lectrique selon votre usage quotidien et votre budget.','["Les hybrides combinent moteur thermique et Ã©lectrique pour optimiser l''Ã©nergie et rÃ©duire les Ã©missions, tandis que les Ã©lectriques fonctionnent uniquement sur batterie, sans Ã©missions Ã  l''usage.", "Les hybrides offrent plus d''autonomie et de flexibilitÃ© pour les longs trajets, avec moins de carburant qu''une essence, mais un coÃ»t d''achat plus Ã©levÃ©.", "Les Ã©lectriques affichent zÃ©ro Ã©mission, moins de carburant et moins d''entretien, mais autonomie et recharge restent des points de vigilance.", "Le choix dÃ©pend de vos trajets (urbains ou longs), de votre budget, des aides disponibles et des infrastructures de recharge. Venez essayer nos modÃ¨les hybrides et Ã©lectriques Ã  Bad Homburg vor der HÃ¶he."]'::jsonb,'2026-01-01T01:50:00Z');
