insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('boite-automatique-dsg-fiabilite','BoÃ®te automatique DSG, 8G-DCT, Steptronic : fiabilitÃ© et entretien','2026-09-12','assets/img/mercedes-classe-a.jpg','Double embrayage, convertisseur, vidanges : comment choisir et entretenir une boÃ®te auto d''occasion sans mauvaise surprise.','["Neuf occasions sur dix vendues chez KlarDrive sont en boÃ®te automatique : DSG chez Volkswagen, 8G-DCT chez Mercedes, Steptronic chez BMW, S tronic chez Audi. Confort en ville, consommation optimisÃ©e : le marchÃ© a tranchÃ©.", "Chaque technologie a ses rÃ¨gles : les doubles embrayages exigent une vidange tous les 60 000 km environ ; les boÃ®tes Ã  convertisseur sont plus tolÃ©rantes mais apprÃ©cient une vidange tous les 80 000 Ã  100 000 km. Une vidange coÃ»te 250 Ã  500 â‚¬ et double la durÃ©e de vie.", "Ã€ l''essai, traquez les Ã -coups au dÃ©marrage, les patinages entre 2e et 3e et les voyants de boÃ®te. Exigez les factures de vidange : une boÃ®te sans entretien Ã  150 000 km est un risque.", "Nos occasions sont diagnostiquÃ©es valise incluse, vidanges vÃ©rifiÃ©es. Un doute sur une boÃ®te ? Ã‰crivez Ã  contact@klardrive.de : diagnostic avant achat possible."]'::jsonb,'2026-01-01T01:56:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('jeune-conducteur-assurance','Jeune conducteur en Allemagne : assurance, SF-Klassen et bonnes voitures','2026-09-09','assets/img/renault-captur.jpg','Classes de bonus, conduite accompagnÃ©e, modÃ¨les pas chers Ã  assurer : le guide du premier achat auto pour rouler serein.','["En Allemagne, l''assurance auto fonctionne par classes de bonus-malus (SF-Klassen) : un jeune conducteur dÃ©marre souvent en SF 1/2 ou SF 0, avec des tarifs Ã©levÃ©s la premiÃ¨re annÃ©e. Chaque annÃ©e sans sinistre fait grimper la classe et baisser la prime.", "Le choix de la voiture change tout : une petite essence de 90 Ã  120 ch coÃ»te deux fois moins cher Ã  assurer qu''une berline puissante. Comparez la Typklasse du modÃ¨le avant d''acheter : elle dÃ©termine le tarif.", "Trois astuces : assurer le vÃ©hicule au nom d''un parent avec le jeune en conducteur additionnel, choisir une franchise plus Ã©levÃ©e, et regrouper assurance auto et habitation chez le mÃªme assureur.", "Notre Ã©quipe conseille les jeunes conducteurs du Hochtaunuskreis chaque semaine : modÃ¨les Ã©conomiques, assurance, financement dÃ¨s 139 â‚¬/mois. Ã‰crivez Ã  contact@klardrive.de."]'::jsonb,'2026-01-01T01:57:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('pneus-hiver-obligation','Pneus hiver en Allemagne : obligation, dates et budget','2026-09-05','assets/img/volvo-xc60-ultimate-t8-dark-recharge-awd.jpg','Obligation situationnelle, amende de 60 â‚¬, marquage 3PMSF : tout savoir pour rouler lÃ©gal dÃ¨s les premiÃ¨res neiges dans le Taunus.','["En Allemagne, pas de date couperet : l''obligation est situationnelle. DÃ¨s que verglas, neige fondue ou givre apparaissent, les pneus hiver sont obligatoires sous peine de 60 â‚¬ d''amende et d''un point Ã  Flensburg â€” et l''assurance peut refuser d''indemniser en cas d''accident.", "Seuls les pneus marquÃ©s 3PMSF (flocon dans une montagne Ã  trois pics) sont reconnus ; le simple marquage M+S ne suffit plus. Comptez 400 Ã  800 â‚¬ le train complet montÃ©-Ã©quilibrÃ© pour une berline ou un SUV.", "Dans le Taunus, Ã©quipez-vous dÃ¨s octobre : les hauteurs autour de Bad Homburg, KÃ¶nigstein et Usingen gÃ¨lent tÃ´t. VÃ©rifiez aussi la roue de secours ou le kit anti-crevaison et le niveau de lave-glace antigel.", "Nos vÃ©hicules sont livrÃ©s avec des pneus contrÃ´lÃ©s et, sur demande, un train hiver montÃ©. PrÃ©parez l''hiver avec KlarDrive : contact@klardrive.de."]'::jsonb,'2026-01-01T01:58:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('reprise-ancien-vehicule','Reprise de votre ancienne voiture : comment en tirer le meilleur prix','2026-09-02','assets/img/toyota-corolla.jpg','Cote, prÃ©sentation, CT Ã  jour : les 5 leviers pour maximiser la reprise de votre vÃ©hicule.','["Faire reprendre son ancienne voiture simplifie l''achat : pas d''annonces, pas d''essais avec des inconnus, et la valeur de reprise vient en dÃ©duction du prix. Mais une reprise mal prÃ©parÃ©e peut coÃ»ter 1 000 Ã  2 000 â‚¬.", "Cinq leviers : un contrÃ´le technique valide de moins de 6 mois ; un carnet d''entretien complet ; une prÃ©sentation impeccable ; les deux clÃ©s et tous les accessoires ; et au moins deux estimations pour nÃ©gocier.", "MÃ©fiez-vous des offres de reprise gonflÃ©es qui cachent une remise inexistante sur la nouvelle voiture : comparez toujours le prix net, reprise dÃ©duite. Une reprise honnÃªte se fait sur la valeur marchÃ© rÃ©elle.", "KlarDrive reprend votre vÃ©hicule au juste prix avec offre Ã©crite en 24 h. Envoyez photos et kilomÃ©trage par e-mail Ã  contact@klardrive.de."]'::jsonb,'2026-01-01T01:59:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('diesel-umweltzone-vignette','Diesel et zones environnementales : vignette verte et interdictions','2026-08-28','assets/img/bmw-x1-xdrive18d.jpg','Umweltplakette, Fahrverbote, Euro 6 : peut-on encore acheter un diesel d''occasion en Allemagne en 2026 ?','["Pour entrer dans les zones environnementales de Francfort et des grandes villes, la vignette verte est obligatoire : 5 Ã  15 â‚¬, valable Ã  vie du vÃ©hicule. Sans elle, 100 â‚¬ d''amende.", "Les interdictions de circulation visent les vieux diesels Euro 4 et moins, et localement certains Euro 5. Un diesel Euro 6 avec AdBlue reste autorisÃ© partout et c''est le seul diesel Ã  acheter en occasion aujourd''hui.", "Le diesel garde du sens pour les gros rouleurs : 5 Ã  6 L/100 km sur autoroute contre 8 Ã  9 pour une essence Ã©quivalente, soit 1 500 â‚¬ d''Ã©conomie annuelle Ã  25 000 km/an. En dessous de 15 000 km/an, prÃ©fÃ©rez l''essence ou l''hybride.", "Notre stock privilÃ©gie les diesels Euro 6 rÃ©cents avec vignette verte fournie. VÃ©rifiez la norme de n''importe quel modÃ¨le par e-mail Ã  contact@klardrive.de."]'::jsonb,'2026-01-01T02:00:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('essai-avant-achat-checklist','Essai d''une occasion : la check-list en 15 points avant de signer','2026-08-25','assets/img/nissan-xtrail.jpg','DÃ©marrage Ã  froid, freinage, Ã©lectronique : les 15 vÃ©rifications qui rÃ©vÃ¨lent l''Ã©tat rÃ©el d''une voiture.','["Un essai de 30 minutes rÃ©vÃ¨le plus qu''une heure d''inspection statique : exigez un dÃ©marrage Ã  froid, puis 15 minutes de ville et 15 minutes de voie rapide autour de Bad Homburg ou sur l''A661.", "En roulant, vÃ©rifiez : direction droite sans tirer, freinage sans vibration, boÃ®te sans Ã -coups, climatisation froide et chaude, tous les voyants Ã©teints aprÃ¨s dÃ©marrage, Ã©lectronique complÃ¨te et bruits suspects.", "Ã€ l''arrÃªt : niveaux d''huile et de refroidissement, usure uniforme des pneus, jeu dans la direction, historique d''entretien et concordance des numÃ©ros entre carte grise et chÃ¢ssis. Refusez tout essai limitÃ© Ã  un parking.", "Chez KlarDrive, chaque essai est libre et le contrÃ´le final a lieu en votre prÃ©sence. RÃ©servez votre essai Ã  contact@klardrive.de."]'::jsonb,'2026-01-01T02:01:00Z');
